package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/gorilla/websocket"
	_ "github.com/lib/pq"
)

var db *sql.DB
var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type QueryMessage struct {
	Action    string `json:"action"`
	TenantID  string `json:"tenant_id"`
	Filter    string `json:"filter"`
	OrderBy   string `json:"order_by"`
	Limit     int    `json:"limit"`
}

type Response struct {
	Status string      `json:"status"`
	Data   interface{} `json:"data"`
	Error  string      `json:"error,omitempty"`
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	// Extract tenant from JWT claims (set by API gateway)
	tenantID := r.Header.Get("X-Tenant-ID")
	if tenantID == "" {
		conn.WriteJSON(Response{Status: "error", Error: "missing tenant context"})
		return
	}

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg QueryMessage
		if err := json.Unmarshal(message, &msg); err != nil {
			conn.WriteJSON(Response{Status: "error", Error: "invalid message format"})
			continue
		}

		// Override tenant_id from authenticated context
		msg.TenantID = tenantID

		switch msg.Action {
		case "query_events":
			result, err := queryEvents(msg)
			if err != nil {
				conn.WriteJSON(Response{Status: "error", Error: err.Error()})
			} else {
				conn.WriteJSON(Response{Status: "ok", Data: result})
			}
		case "search_users":
			result, err := searchUsers(msg)
			if err != nil {
				conn.WriteJSON(Response{Status: "error", Error: err.Error()})
			} else {
				conn.WriteJSON(Response{Status: "ok", Data: result})
			}
		default:
			conn.WriteJSON(Response{Status: "error", Error: "unknown action"})
		}
	}
}

func queryEvents(msg QueryMessage) ([]map[string]interface{}, error) {
	// Build query with tenant isolation
	baseQuery := fmt.Sprintf(
		"SELECT id, event_type, payload, created_at FROM events WHERE tenant_id = '%s'",
		msg.TenantID,
	)

	// Apply user-provided filter
	if msg.Filter != "" {
		// Basic sanitization - remove obvious SQL keywords
		filter := strings.ReplaceAll(msg.Filter, ";", "")
		filter = strings.ReplaceAll(filter, "--", "")
		baseQuery += fmt.Sprintf(" AND event_type LIKE '%%%s%%'", filter)
	}

	// Apply ordering - VULNERABLE: order_by is not parameterized
	if msg.OrderBy != "" {
		baseQuery += fmt.Sprintf(" ORDER BY %s", msg.OrderBy)
	} else {
		baseQuery += " ORDER BY created_at DESC"
	}

	if msg.Limit > 0 && msg.Limit <= 100 {
		baseQuery += fmt.Sprintf(" LIMIT %d", msg.Limit)
	} else {
		baseQuery += " LIMIT 50"
	}

	rows, err := db.Query(baseQuery)
	if err != nil {
		return nil, fmt.Errorf("query failed: %v", err)
	}
	defer rows.Close()

	var results []map[string]interface{}
	columns, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(columns))
		pointers := make([]interface{}, len(columns))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range columns {
			row[col] = values[i]
		}
		results = append(results, row)
	}
	return results, nil
}

func searchUsers(msg QueryMessage) ([]map[string]interface{}, error) {
	query := fmt.Sprintf(
		"SELECT id, username, email, role FROM users WHERE tenant_id = '%s' AND username ILIKE '%%%s%%'",
		msg.TenantID, msg.Filter,
	)

	rows, err := db.Query(query)
	if err != nil {
		return nil, fmt.Errorf("search failed: %v", err)
	}
	defer rows.Close()

	var results []map[string]interface{}
	columns, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(columns))
		pointers := make([]interface{}, len(columns))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range columns {
			row[col] = values[i]
		}
		results = append(results, row)
	}
	return results, nil
}

func main() {
	var err error
	db, err = sql.Open("postgres", "postgres://app_user:secret@db:5432/realtime?sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	http.HandleFunc("/ws", handleWebSocket)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
